#!/usr/bin/env bash
# RHACS SecuredCluster needs an init bundle generated by Central. It contains
# cluster credentials, so it is created here rather than committed.
source "$(dirname "$0")/lib.sh"
require_cluster

step "Waiting for RHACS Central"
wait_for "central deployment" 900 \
  oc rollout status deploy/central -n stackrox --timeout=10s

if oc get secret sensor-tls -n stackrox >/dev/null 2>&1; then
  ok "init bundle already applied (sensor-tls exists)"
  exit 0
fi

step "Generating the init bundle"
PASS="$(oc get secret central-htpasswd -n stackrox -o jsonpath='{.data.password}' | base64 -d)"
TMP="$(mktemp -d)"; trap 'rm -rf "${TMP}"' EXIT

oc exec -n stackrox deploy/central -- \
  roxctl --insecure-skip-tls-verify -e central.stackrox.svc:443 \
  -p "${PASS}" central init-bundles generate lightwell-inward-demo \
  --output-secrets=- > "${TMP}/bundle.yaml"

grep -q 'kind: Secret' "${TMP}/bundle.yaml" || die "init bundle generation produced no secrets"
oc apply -n stackrox -f "${TMP}/bundle.yaml"
ok "init bundle applied"

step "Waiting for the sensor to connect"
wait_for "sensor deployment" 600 \
  oc rollout status deploy/sensor -n stackrox --timeout=10s
wait_for "admission controller" 600 \
  oc rollout status deploy/admission-control -n stackrox --timeout=10s
ok "RHACS is securing this cluster"
